export async function isEndpointAvailableFetch(endpoint) {
    const response = await fetch(process.env.BREAKLIMIT_WEBSITE_URL+`/endpointavailable/${endpoint}`, {
        method: "GET",
        headers: {
            "Content-Type": "application/json",
        }
    });

